export function getCommon(key: string, lang: Lang): string {
  const packed = getLocalePackText(lang, key);
  if (packed) return packed;

  const parts = key.split('.');
  let current: unknown = COMMON;
  for (const part of parts) {
    if (current && typeof current === 'object' && part in current) {
      current = (current as Record<string, unknown>)[part];
    } else {
      return key;
    }
  }
  if (current && typeof current === 'object' && current !== null) {
    const loc = current as LocalizedString;
    for (const code of LANG_FALLBACK[lang]) {
      const text = loc[code];
      if (typeof text === 'string' && text.length > 0) return text;
    }
  }
  if (typeof current === 'string') return current;
  return key;
}

export function getCommonParams(
  key: string,
  lang: Lang,
  params: Record<string, string | number>,
): string {
  let text = getCommon(key, lang);
  for (const [name, value] of Object.entries(params)) {
    text = text.split(`{${name}}`).join(String(value));
  }
  return text;
}

/** Build a LocalizedString from a dot-key in COMMON (for resolveLocalized). */
export function getCommonLocalized(key: string): LocalizedString {
  const out = {} as LocalizedString;
  for (const code of APP_LANGS) {
    out[code] = getCommon(key, code);
  }
  return out;
}
